export const addTestProducts = async () => {
  console.log("Adding test products...");
  
  for (let i = 0; i < testProducts.length; i++) {
    try {
      const response = await productAPI.create(testProducts[i]);
      console.log(`Product ${i + 1} added:`, testProducts[i].name);
    } catch (error) {
      console.error(`Failed to add product ${i + 1}:`, error);
    }
  }
  
  console.log("Finished adding test products!");
};

export default addTestProducts;